class Originator {
  private state: string;
  constructor(s: string) { this.state = s; }
  createSnapshot() { return { state: this.state }; }
  restore(snapshot: { state: string }) { this.state = snapshot.state; }
}

class Caretaker {
  private history: any[] = [];
  save(o: Originator) { this.history.push(o.createSnapshot()); }
  restore(o: Originator, i: number) { o.restore(this.history[i]); }
}

class Originator {
  private data: any;
  createSnapshot() { return { data: this.data }; }
  restore(s: any) { this.data = s.data; }
}

class Caretaker {
  private snapshots: any[] = [];
  add(o: Originator) { this.snapshots.push(o.createSnapshot()); }
  // snapshots array grows without bounds
}

// Version A
class OriginatorA {
  private state: any;
  createSnapshot() { return new SnapshotA(this.state); }
  restore(s: SnapshotA) { this.state = s.getState(); }
}
class CaretakerA { private bank: any[] = []; save(s: any) { this.bank.push(s); } }

// Version B
class OriginatorB {
  private state: any;
  createSnapshot() { return { state: this.state }; }
  restore(s: any) { this.state = s.state; }
}
class CaretakerB { private bank: any[] = []; save(s: any) { console.log(s.state); this.bank.push(s); } }
